   pure module subroutine cfc_pair_hessian_eval_faded(d_a, d_b, R_a, R_b, a2, c_par, fade_start, &
                                               fade_width, max_deriv, qq0_aa, qq0_ab, qq0_bb, &
                                               qq1_r_aa, qq1_r_ab, qq1_r_bb, qq2_rr_aa, &
