      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dr_a dr_a) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq0_aa(3, 3)
      !> d2/(dr_a dr_b) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq0_ab(3, 3)
      !> d2/(dr_b dr_b) of the order-0 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq0_bb(3, 3)
      !> d2/(dr_a dr_a) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq1_r_aa(3, 3, 3)
      !> d2/(dr_a dr_b) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq1_r_ab(3, 3, 3)
      !> d2/(dr_b dr_b) of the order-1 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq1_r_bb(3, 3, 3)
      !> d2/(dr_a dr_a) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and a
      real(wp), intent(inout) :: qq2_rr_aa(3, 3, 3, 3)
      !> d2/(dr_a dr_b) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms a and b
      real(wp), intent(inout) :: qq2_rr_ab(3, 3, 3, 3)
      !> d2/(dr_b dr_b) of the order-2 spatial derivative; the two trailing indices are the nuclear
      !> components of atoms b and b
      real(wp), intent(inout) :: qq2_rr_bb(3, 3, 3, 3)
      !> Reduced distance sigma = ||d_a||/R_a - 1 of center a
      real(wp), intent(in) :: sg_a
      !> Reduced distance sigma = ||d_b||/R_b - 1 of center b
      real(wp), intent(in) :: sg_b

      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      if (.not. fade_width > 0.0_wp) error stop &
         "cfc_pair_hessian_eval: fade_width must be positive"
      band_end = fade_start + fade_width
      ! Beyond the band of a center: w = 0, nothing to add
      if (sg_a >= band_end .or. sg_b >= band_end) return
      inv_delta = 1.0_wp/fade_width
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
            real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
            real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
            real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
            real(wp) :: x77, x78, x79, x80, t_qq0_aa_01, t_qq0_aa_02, t_qq0_aa_12, t_qq0_bb_01
            real(wp) :: t_qq0_bb_02, t_qq0_bb_12

            sr = (band_end - (sg_a))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fu = exp(a2*(sg_a + sg_b))
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_a(0) = fj0*fu
            g_a(1) = fu*(a2*fj0 + fj1)
            g_a(2) = &
               fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2))
            sr = (band_end - (sg_b))*inv_delta
            fs = min(max(sr, 0.0_wp), 1.0_wp)
            ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
            dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
            fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
            fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
            fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
            fsp1 = fs
            fsp2 = fsp1*fs
            fsp3 = fsp2*fs
            fsp4 = fsp3*fs
            fsp5 = fsp4*fs
            fj0 = fp0*fsp5
            fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
            g_b(0) = fj0
            g_b(1) = a2*fj0 + fj1
            g_b(2) = &
               (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
               fp2*fsp2)
            x0 = (d_b(1)*d_b(1))
            x1 = 1.0_wp/(R_b*R_b)
            x2 = x0*x1
            x3 = 1.0_wp/(R_a*R_a)
            x4 = d_a(1)*d_b(1)
            x5 = d_a(2)*d_b(2)
            x6 = d_a(3)*d_b(3)
            x7 = 1.0_wp/R_a
            x8 = 1.0_wp/R_b
            x9 = x7*x8
            x10 = -x9*(x4 + x5 + x6) + 1.0_wp
            x11 = (x10*x10)
            x12 = c_par*g_a(0)*g_b(0)
            x13 = 12.0_wp*x11*x12
            x14 = x13*x3
            x15 = (d_a(1)*d_a(1))
            x16 = (d_a(2)*d_a(2))
            x17 = (d_a(3)*d_a(3))
            x18 = x15 + x16 + x17
            x19 = 1.0_wp/sqrt(x18)
            x20 = g_a(1)*x19
            x21 = (x10*x10*x10*x10)
            x22 = c_par*x21
            x23 = g_b(0)*x22
            x24 = x23*x7
            x25 = x20*x24
            x26 = x15*x3
            x27 = 1.0_wp/x18
            x28 = g_a(2)*x23*x27
            x29 = g_a(1)*x24/(x18*sqrt(x18))
            x30 = (x10*x10*x10)
            x31 = 8.0_wp*c_par*x30
            x32 = x31*x4
            x33 = g_b(0)*x20*x8
            x34 = x3*x33
            x35 = d_a(1)*d_a(2)
            x36 = 4.0_wp*x30
            x37 = c_par*x36
            x38 = x33*x37
            x39 = x3*x38
            x40 = d_a(1)*x39
            x41 = d_b(1)*x39
            x42 = d_a(1)*d_a(3)
            x43 = (d_b(2)*d_b(2))
            x44 = x1*x14
            x45 = x28*x3
            x46 = x31*x34
            x47 = d_a(2)*d_a(3)
            x48 = d_a(2)*d_b(3)
            x49 = d_a(3)*d_b(2)
            x50 = (d_b(3)*d_b(3))
            x51 = x12*x36*x9
            x52 = x0 + x43 + x50
            x53 = 1.0_wp/sqrt(x52)
            x54 = g_b(1)*x53
            x55 = g_a(0)*x54*x7
            x56 = x37*x55
            x57 = d_b(1)*x44
            x58 = x20*x22*x54*x9
            x59 = d_a(1)*x58
            x60 = d_b(1)*d_b(2)
            x61 = x1*x56
            x62 = -x35*x39 - x60*x61
            x63 = d_b(1)*d_b(3)
            x64 = -x39*x42 - x61*x63
            x65 = d_b(2)*x44
            x66 = d_b(1)*x58
            x67 = d_b(2)*d_b(3)
            x68 = -x39*x47 - x61*x67
            x69 = d_b(3)*x44
            x70 = g_a(0)*x22
            x71 = x70*x8
            x72 = x54*x71
            x73 = 1.0_wp/x52
            x74 = g_b(2)*x70*x73
            x75 = g_b(1)*x71/(x52*sqrt(x52))
            x76 = x1*x55
            x77 = d_a(1)*x61
            x78 = d_b(1)*x61
            x79 = x1*x74
            x80 = x31*x76
            qq0_aa(1, 1) = qq0_aa(1, 1) + (x14*x2 - x15*x29 + x25 + x26*x28 - x32*x34)
            t_qq0_aa_01 = &
               c_par*d_a(1)*d_a(2)*g_a(2)*g_b(0)*x21*x27*x3 + &
               12.0_wp*c_par*d_b(1)*d_b(2)*g_a(0)*g_b(0)*x1*x11*x3 - d_a(2)*x41 - d_b(2)*x40 - &
               x29*x35
            qq0_aa(1, 2) = qq0_aa(1, 2) + t_qq0_aa_01
            qq0_aa(2, 1) = qq0_aa(2, 1) + t_qq0_aa_01
            t_qq0_aa_02 = &
               c_par*d_a(1)*d_a(3)*g_a(2)*g_b(0)*x21*x27*x3 + &
               12.0_wp*c_par*d_b(1)*d_b(3)*g_a(0)*g_b(0)*x1*x11*x3 - d_a(3)*x41 - d_b(3)*x40 - &
               x29*x42
            qq0_aa(1, 3) = qq0_aa(1, 3) + t_qq0_aa_02
            qq0_aa(3, 1) = qq0_aa(3, 1) + t_qq0_aa_02
            qq0_aa(2, 2) = qq0_aa(2, 2) + (-x16*x29 + x16*x45 + x25 + x43*x44 - x46*x5)
            t_qq0_aa_12 = &
               c_par*d_a(2)*d_a(3)*g_a(2)*g_b(0)*x21*x27*x3 + &
               12.0_wp*c_par*d_b(2)*d_b(3)*g_a(0)*g_b(0)*x1*x11*x3 - x29*x47 - x39*x48 - x39*x49
            qq0_aa(2, 3) = qq0_aa(2, 3) + t_qq0_aa_12
            qq0_aa(3, 2) = qq0_aa(3, 2) + t_qq0_aa_12
            qq0_aa(3, 3) = qq0_aa(3, 3) + (-x17*x29 + x17*x45 + x25 + x44*x50 - x46*x6)
            qq0_ab(1, 1) = &
               qq0_ab(1, 1) + (12.0_wp*c_par*d_a(1)*d_b(1)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_a(1)*d_b(1)*g_a(1)*g_b(1)*x19*x21*x53*x7*x8 - x2*x56 - x26*x38 - x51)
            qq0_ab(1, 2) = qq0_ab(1, 2) + (d_a(2)*x57 + d_b(2)*x59 + x62)
            qq0_ab(1, 3) = qq0_ab(1, 3) + (d_a(3)*x57 + d_b(3)*x59 + x64)
            qq0_ab(2, 1) = qq0_ab(2, 1) + (d_a(1)*x65 + d_a(2)*x66 + x62)
            qq0_ab(2, 2) = &
               qq0_ab(2, 2) + (12.0_wp*c_par*d_a(2)*d_b(2)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_a(2)*d_b(2)*g_a(1)*g_b(1)*x19*x21*x53*x7*x8 - x16*x39 - x43*x61 - x51)
            qq0_ab(2, 3) = qq0_ab(2, 3) + (d_a(3)*x65 + x48*x58 + x68)
            qq0_ab(3, 1) = qq0_ab(3, 1) + (d_a(1)*x69 + d_a(3)*x66 + x64)
            qq0_ab(3, 2) = qq0_ab(3, 2) + (d_a(2)*x69 + x49*x58 + x68)
            qq0_ab(3, 3) = &
               qq0_ab(3, 3) + (12.0_wp*c_par*d_a(3)*d_b(3)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_a(3)*d_b(3)*g_a(1)*g_b(1)*x19*x21*x53*x7*x8 - x17*x39 - x50*x61 - x51)
            qq0_bb(1, 1) = qq0_bb(1, 1) + (-x0*x75 + x1*x13*x26 + x2*x74 - x32*x76 + x72)
            t_qq0_bb_01 = &
               12.0_wp*c_par*d_a(1)*d_a(2)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_b(1)*d_b(2)*g_a(0)*g_b(2)*x1*x21*x73 - d_a(2)*x78 - d_b(2)*x77 - x60*x75
            qq0_bb(1, 2) = qq0_bb(1, 2) + t_qq0_bb_01
            qq0_bb(2, 1) = qq0_bb(2, 1) + t_qq0_bb_01
            t_qq0_bb_02 = &
               12.0_wp*c_par*d_a(1)*d_a(3)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_b(1)*d_b(3)*g_a(0)*g_b(2)*x1*x21*x73 - d_a(3)*x78 - d_b(3)*x77 - x63*x75
            qq0_bb(1, 3) = qq0_bb(1, 3) + t_qq0_bb_02
            qq0_bb(3, 1) = qq0_bb(3, 1) + t_qq0_bb_02
            qq0_bb(2, 2) = qq0_bb(2, 2) + (x16*x44 - x43*x75 + x43*x79 - x5*x80 + x72)
            t_qq0_bb_12 = &
               12.0_wp*c_par*d_a(2)*d_a(3)*g_a(0)*g_b(0)*x1*x11*x3 + &
               c_par*d_b(2)*d_b(3)*g_a(0)*g_b(2)*x1*x21*x73 - x48*x61 - x49*x61 - x67*x75
            qq0_bb(2, 3) = qq0_bb(2, 3) + t_qq0_bb_12
            qq0_bb(3, 2) = qq0_bb(3, 2) + t_qq0_bb_12
            qq0_bb(3, 3) = qq0_bb(3, 3) + (x17*x44 - x50*x75 + x50*x79 - x6*x80 + x72)
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
